// String Air / Size: Suno Studio audio effect for the STRINGS stem (applied to rendered audio, not a lyric tag).
// Signal chain, in order:
//   1. Input trim: convert 'input gain' dB to linear and scale each channel.
//   2. Air: g.biquad highshelf near 10kHz driven by 'air' dB for silky top end.
//   3. Body: g.biquad lowshelf near 300Hz driven by 'body' dB to control low-mid weight.
//   4. Size/tilt: shelving pair for the distant-to-chamber balance. Lowshelf -size near 200Hz and highshelf
//      +size near 6kHz (opposite directions via g.mul by -1) driven by one 'size/tilt' param; higher opens
//      the sound out to a larger, brighter chamber, lower keeps it close and intimate.
//   5. Saturation: scale by 'saturation' (dB via g.dbToLin) then g.tanh for gentle body.
//   6. Dry/wet: g.lerp between trimmed dry and processed by 'dry/wet mix'.
//   7. Output gain, bypass select via g.lerp, then g.tanh safety before g.output.
// Bypass: g.lerp(bypass, out, trimmed) ASSUMES the 'bypass' enum resolves to 0 ('off') / 1 ('on'), so
// 'off' passes the PROCESSED signal and 'on' passes the DRY signal (see AUTHORING.md).
// ASSUMPTION: the shelf g.biquad stages pass a 'gainDb' field not confirmed from the one example (see AUTHORING.md).
function build(g, config) {
  var inL = g.input('audioInL');
  var inR = g.input('audioInR');

  var inGainDb = g.input('input gain');
  var airDb = g.input('air');
  var bodyDb = g.input('body');
  var sizeDb = g.input('size/tilt');
  var satDb = g.input('saturation');
  var mixPct = g.input('dry/wet mix');
  var outGainDb = g.input('output gain');
  var bypass = g.input('bypass');

  var inGain = g.dbToLin(inGainDb);
  var outGain = g.dbToLin(outGainDb);
  var satLin = g.dbToLin(satDb);
  var mix = g.clamp(g.div(mixPct, g.constant(100)), g.zero(), g.constant(1));
  var negSize = g.mul(sizeDb, g.constant(-1));

  function chain(x) {
    var trimmed = g.mul(x, inGain);
    var air = g.biquad({ input: trimmed, cutoff: g.constant(10000), resonance: g.constant(0.707), mode: 'highshelf', gainDb: airDb });
    var body = g.biquad({ input: air, cutoff: g.constant(300), resonance: g.constant(0.707), mode: 'lowshelf', gainDb: bodyDb });
    var sizeLow = g.biquad({ input: body, cutoff: g.constant(200), resonance: g.constant(0.707), mode: 'lowshelf', gainDb: negSize });
    var sized = g.biquad({ input: sizeLow, cutoff: g.constant(6000), resonance: g.constant(0.707), mode: 'highshelf', gainDb: sizeDb });
    var sat = g.tanh(g.mul(sized, satLin));
    var wet = g.lerp(mix, trimmed, sat);
    var out = g.mul(wet, outGain);
    var active = g.lerp(bypass, out, trimmed);
    return g.tanh(active);
  }

  g.output('audioOutL', chain(inL));
  g.output('audioOutR', chain(inR));
}
